// ── map-hosting.js: /** Maximum number of mapped documents in one ho ──
/** Maximum number of mapped documents in one host chain. */
const MAX_HOSTED_MAP_DEPTH = 3;

function resolveHostArea(hostDocument, asset) {
    const area = (hostDocument.areas || []).find(item => item.id === asset.location);
    if (!area) throw new Error(`Hosted asset "${asset.name}" does not occupy a valid parent-map cell.`);
    return area;
}

/** Canonical Locations-lore path for a peer hosted by an asset in any map cell. */
function buildHostedPeerSitePath(hostDocument, asset) {
    const area = resolveHostArea(hostDocument, asset);
    return `${hostDocument.site} :: ${area.name} :: ${asset.name}`;
}

/** Reparent a mapped peer root and every descendant Location breadcrumb. */
function reparentHostedLocationEntries(entries, entry, canonicalSite, requestedSite) {
    const oldLabel = String(entry?.comment || '').trim();
    const nextLabel = String(canonicalSite || '').trim();
    if (!oldLabel || !nextLabel || oldLabel === nextLabel) return false;
    for (const candidate of Object.values(entries || {})) {
        if (!candidate || candidate === entry) continue;
        const label = String(candidate.comment || '').trim();
        if (label.startsWith(`${oldLabel} :: `)) {
            candidate.comment = `${nextLabel}${label.slice(oldLabel.length)}`;
        }
    }
    entry.comment = nextLabel;
    entry.key = [...new Set([
        requestedSite,
        nextLabel,
        ...(Array.isArray(entry.key) ? entry.key : []),
    ].map(value => String(value || '').trim()).filter(Boolean))].slice(0, 6);
    rebaseHostedMapDocuments(entries, oldLabel, nextLabel);
    return true;
}

/** Keep every mapped descendant's runtime-owned host chain aligned after reparenting. */
function rebaseHostedMapDocuments(entries, oldPrefix, newPrefix) {
    const oldRoot = String(oldPrefix || '').trim();
    const newRoot = String(newPrefix || '').trim();
    if (!oldRoot || !newRoot || oldRoot === newRoot) return false;
    const rebase = value => {
        const text = String(value || '').trim();
        if (text === oldRoot) return newRoot;
        return text.startsWith(`${oldRoot} :: `) ? `${newRoot}${text.slice(oldRoot.length)}` : text;
    };
    let changed = false;
    for (const candidate of Object.values(entries || {})) {
        const attachment = getDungeonMapAttachment(candidate);
        if (!attachment) continue;
        const document = parseDungeonMapDocument(attachment.content, attachment.siteRoot).document;
        const nextSite = rebase(document.site);
        const nextHost = rebase(document.hostSite);
        if (nextSite === document.site && nextHost === String(document.hostSite || '').trim()) continue;
        document.site = nextSite;
        if (nextHost) document.hostSite = nextHost;
        if (document.hostBrief) document.hostBrief = String(document.hostBrief).split(oldRoot).join(newRoot);
        if (document.hostSite && document.hostBrief) {
            candidate.content = ensureHostCoreMirror(candidate.content, document.hostSite, document.hostBrief);
        }
        candidate.content = replaceDungeonMapSection(candidate.content, serializeDungeonMapDocument(document));
        changed = true;
    }
    return changed;
}

/** Mirror runtime-owned host metadata inside an existing CORE block, idempotently. */
function ensureHostCoreMirror(content, hostSite, hostBrief) {
    const source = String(content || '');
    const hostLines = `Host Site: ${hostSite}\nHost Brief: ${hostBrief}`;
    const core = source.match(/\[CORE\]([\s\S]*?)\[\/CORE\]/i);
    if (!core) return `[CORE]\n${hostLines}\n[/CORE]\n${source}`.trim();
    const cleaned = core[1]
        .replace(/^\s*Host Site:\s*.*(?:\r?\n|$)/gim, '')
        .replace(/^\s*Host Brief:\s*.*(?:\r?\n|$)/gim, '')
        .trim();
    const inner = [cleaned, hostLines].filter(Boolean).join('\n');
    return source.replace(core[0], `[CORE]\n${inner}\n[/CORE]`);
}

/** Build the canonical compact exit packet from the host map cell. */
function buildHostedPeerBrief(hostDocument, asset) {
    const area = resolveHostArea(hostDocument, asset);
    const fact = String(area.geometry?.[0] || '').trim();
    return `Contained in ${hostDocument.site}, ${area.name}.${fact ? ` ${fact}` : ''} Exit returns to ${area.name} in ${hostDocument.site}.`
        .replace(/\s+/g, ' ')
        .trim();
}

/** Stamp a DUNGEON/INTERIOR peer, rejecting conflicting re-hosts. */
function stampHostedPeerDocument(peerDocument, hostDocument, asset) {
    if (!['DUNGEON', 'INTERIOR'].includes(normalizeMapSiteKind(peerDocument.kind))) {
        throw new Error(`Hosted peer "${peerDocument.site}" must be DUNGEON or INTERIOR.`);
    }
    if (peerDocument.hostSite && peerDocument.hostSite !== hostDocument.site) {
        throw new Error(`Mapped peer "${peerDocument.site}" is already hosted inside "${peerDocument.hostSite}".`);
    }
    if (!['SETTLEMENT', 'DUNGEON', 'INTERIOR'].includes(normalizeMapSiteKind(hostDocument.kind))) {
        throw new Error(`Host "${hostDocument.site}" is not a supported mapped site.`);
    }
    const stamped = JSON.parse(JSON.stringify(peerDocument));
    stamped.hostSite = hostDocument.site;
    stamped.hostBrief = buildHostedPeerBrief(hostDocument, asset);
    return stamped;
}

// ── map-hosting-context.js: export function normalizeMapAttachment(value) { ──
function normalizeMapAttachment(value) {
    if (value == null) return null;
    if (typeof value !== 'object' || Array.isArray(value)) {
        throw attachmentFailure('attachTo must be an object containing exact site and cell strings.');
    }
    const site = String(value.site || '').trim();
    const cell = String(value.cell || '').trim();
    if (!site && !cell) throw attachmentFailure('attachTo requires both site and cell. Omit attachTo entirely for a standalone map.');
    return { site, cell };
}

function attachmentFailure(message) {
    return new Error(`[MAP_ARCHITECT_ATTACHMENT_ERROR — PRIVATE]\n${message}\nCorrect attachTo using the exact names supplied above, then retry CreateAreaMap once. Do not move the player or alter the Location footer.\n[/MAP_ARCHITECT_ATTACHMENT_ERROR]`);
}

function resolveHostChain(record, sites) {
    const chain = [];
    const seen = new Set();
    let cursor = record;
    while (cursor) {
        const key = String(cursor.siteRoot || '').trim();
        if (!key || seen.has(key)) throw attachmentFailure(`The mapped host chain contains a cycle at "${key || '(unnamed site)'}".`);
        seen.add(key);
        chain.push(cursor);
        const document = parseDungeonMapDocument(cursor.mapChunks?.[0], cursor.siteRoot).document;
        const parentSite = String(document.hostSite || '').trim();
        if (!parentSite) break;
        const matches = Object.values(sites || {}).filter(candidate => candidate?.mapChunks?.length
            && dungeonSiteRootsMatch(candidate.siteRoot, parentSite));
        if (matches.length !== 1) {
            throw attachmentFailure(`Could not resolve the direct parent map "${parentSite}" required by "${cursor.siteRoot}".`);
        }
        cursor = matches[0];
    }
    return chain;
}

function buildHostCellPrompt(hostDocument, hostArea) {
    const areasById = new Map((hostDocument.areas || []).map(area => [area.id, area]));
    const routes = (hostArea.connections || []).map(connection => {
        const target = areasById.get(connection.to);
        return `${target?.name || connection.to} (${connection.state})${connection.detail ? ` — ${connection.detail}` : ''}`;
    });
    const assets = (hostDocument.assets || []).filter(asset => asset.location === hostArea.id && asset.state !== 'REMOVED' && asset.state !== 'LEFT');
    return `PARENT MAP CELL (LOCKED CONTEXT)\nParent map: ${hostDocument.site} (${hostDocument.kind})\nTarget cell: ${hostArea.name} [${hostArea.id}]\nCell knowledge: ${hostArea.knowledge}\nGeometry:\n${(hostArea.geometry || []).map(line => `- ${line}`).join('\n') || '- none'}\nParent routes:\n${routes.map(line => `- ${line}`).join('\n') || '- none'}\nExisting parent-cell assets:\n${assets.map(asset => `- ${asset.id}: ${asset.kind} "${asset.name}" (${asset.state}, ${asset.knowledge})${asset.detail ? ` — ${asset.detail}` : ''}`).join('\n') || '- none'}\nThe target cell remains on the parent map and receives the child gateway. The child map begins at its requested entrance. Do not duplicate parent-cell occupants or props inside the child unless the map-generation prompt or recent story explicitly establishes that they crossed the gateway.`;
}

function buildHostTopologyPrompt(hostDocument, hostArea) {
    const areasById = new Map((hostDocument.areas || []).map(area => [area.id, area]));
    const routes = (hostArea.connections || []).map(connection => {
        const target = areasById.get(connection.to);
        return `${target?.name || connection.to} (${connection.state})${connection.detail ? ` — ${connection.detail}` : ''}`;
    });
    return `PARENT MAP CELL (LOCKED STRUCTURAL CONTEXT)\nParent map: ${hostDocument.site} (${hostDocument.kind})\nTarget cell: ${hostArea.name} [${hostArea.id}]\nCell knowledge: ${hostArea.knowledge}\nGeometry:\n${(hostArea.geometry || []).map(line => `- ${line}`).join('\n') || '- none'}\nParent routes:\n${routes.map(line => `- ${line}`).join('\n') || '- none'}\nThe target cell remains on the parent map. The child graph begins at its requested entrance.`;
}

/** Resolve an explicit offsite attachment or the active-map shorthand. */
function resolveHostedCreationContext(current, currentLocation, args) {
    const attachTo = normalizeMapAttachment(args.attachTo);
    if (!['DUNGEON', 'INTERIOR'].includes(args.kind)) {
        if (attachTo) throw attachmentFailure('attachTo is valid only when creating a DUNGEON or INTERIOR child map. SETTLEMENT maps cannot be nested.');
        return null;
    }
    const records = Object.values(current.sites || {}).filter(record => record?.mapChunks?.length);
    let active = null;
    if (attachTo) {
        if (!attachTo.site || !attachTo.cell) {
            throw attachmentFailure('attachTo requires both site (the existing parent map) and cell (the exact parent area).');
        }
        const matches = records.filter(record => dungeonSiteRootsMatch(record.siteRoot, attachTo.site));
        if (matches.length !== 1) {
            const available = records.map(record => record.siteRoot).filter(Boolean).sort();
            throw attachmentFailure(`Parent map "${attachTo.site}" was not found exactly.${available.length ? ` Available mapped sites: ${available.join(', ')}.` : ' No mapped sites are available.'}`);
        }
        active = matches[0];
    } else {
        if (!currentLocation) return null;
        active = resolveActiveDungeonSite({ version: 3, sites: current.sites || {} }, currentLocation);
        if (!active) return null;
    }
    const hostDocument = parseDungeonMapDocument(active.mapChunks[0], active.siteRoot).document;
    const chain = resolveHostChain(active, current.sites || {});
    if (chain.some(record => dungeonSiteRootsMatch(record.siteRoot, args.site))) {
        throw attachmentFailure(`"${args.site}" is already in the selected host's ancestry and cannot be attached beneath itself.`);
    }
    if (chain.length >= MAX_HOSTED_MAP_DEPTH) {
        throw attachmentFailure(`"${active.siteRoot}" is already map level ${chain.length}. Nested maps are limited to ${MAX_HOSTED_MAP_DEPTH} mapped levels.`);
    }
    const exactAssetMatches = (hostDocument.assets || []).filter(asset =>
        asset.state !== 'REMOVED' && asset.state !== 'LEFT' && dungeonLabelIdentitiesMatch(asset.name, args.site));
    if (exactAssetMatches.length > 1) {
        throw attachmentFailure(`Parent map "${active.siteRoot}" contains more than one active asset named "${args.site}".`);
    }
    const exactAsset = exactAssetMatches[0] || null;
    const expectedAssetKind = args.kind === 'INTERIOR' ? 'SUBINTERIOR' : 'SUBDUNGEON';
    if (exactAsset && !['BUILDING', 'OBJECT', expectedAssetKind].includes(exactAsset.kind)) {
        throw attachmentFailure(`Parent-map asset "${args.site}" is ${exactAsset.kind}; ${args.kind} requires ${expectedAssetKind}.`);
    }
    let hostArea = null;
    if (attachTo) {
        const resolved = resolveMapAreaIdentity(hostDocument, attachTo.cell);
        if (!resolved.area) {
            const available = (hostDocument.areas || []).map(area => area.name).filter(Boolean);
            throw attachmentFailure(`Cell "${attachTo.cell}" was not found exactly in "${active.siteRoot}". Available cells: ${available.join(', ') || '(none)'}.`);
        }
        hostArea = resolved.area;
    } else {
        const placement = resolveCurrentMapPlacement(hostDocument, currentLocation);
        hostArea = exactAsset
            ? hostDocument.areas.find(area => area.id === exactAsset.location)
            : placement.area;
        if (!hostArea) return null;
    }
    if (exactAsset && exactAsset.location !== hostArea.id) {
        const actual = (hostDocument.areas || []).find(area => area.id === exactAsset.location)?.name || exactAsset.location;
        throw attachmentFailure(`Asset "${args.site}" already occupies "${actual}", not requested cell "${hostArea.name}".`);
    }
    const hostedAsset = exactAsset || { name: args.site, location: hostArea.id };
    return {
        hostSite: active.siteRoot,
        hostEntryId: active.entryId,
        hostAreaId: hostArea.id,
        assetName: args.site,
        peerSite: buildHostedPeerSitePath(hostDocument, hostedAsset),
        expectedAssetKind,
        briefDescription: args.briefDescription,
        topologyPromptContext: buildHostTopologyPrompt(hostDocument, hostArea),
        promptContext: buildHostCellPrompt(hostDocument, hostArea),
        explicit: !!attachTo,
        hostDepth: chain.length,
        peerDepth: chain.length + 1,
    };
}

// ── router.js: function allocateHostedAssetId(document, name) { ──
function allocateHostedAssetId(document, name) {
    const used = new Set((document.assets || []).map(asset => asset.id));
    const base = `subsite-${mapTransactionSignature(String(name || '')).slice(0, 8)}`;
    if (!used.has(base)) return base;
    let suffix = 2;
    while (used.has(`${base}-${suffix}`)) suffix++;
    return `${base}-${suffix}`;
}

function promoteHostedPeerAsset(hostDocument, site, expectedKind, areaId, briefDescription, { hidden = false } = {}) {
    if (!['SETTLEMENT', 'DUNGEON', 'INTERIOR'].includes(normalizeMapSiteKind(hostDocument.kind))) {
        throw new Error(`Host "${hostDocument.site}" is not a supported mapped site.`);
    }
    const area = (hostDocument.areas || []).find(item => item.id === areaId);
    if (!area) throw new Error(`Could not resolve the host map cell for "${site}".`);
    const matches = (hostDocument.assets || []).filter(asset => dungeonLabelIdentitiesMatch(asset.name, site) && asset.state !== 'REMOVED' && asset.state !== 'LEFT');
    if (matches.length > 1) throw new Error(`Host map contains more than one active asset named "${site}".`);
    let asset = matches[0] || null;
    if (asset) {
        if (![expectedKind, 'BUILDING', 'OBJECT'].includes(asset.kind)) {
            throw new Error(`Host-map asset "${site}" is ${asset.kind}; expected ${expectedKind}.`);
        }
        asset.kind = expectedKind;
        asset.location = area.id;
    } else {
        asset = {
            id: allocateHostedAssetId(hostDocument, site),
            kind: expectedKind,
            name: site,
            location: area.id,
            state: 'ACTIVE',
            knowledge: hidden ? 'UNREVEALED' : 'KNOWN',
            detail: String(briefDescription || '').trim(),
            origin: 'NARRATOR_ESTABLISHED',
        };
        hostDocument.assets.push(asset);
    }
    return asset;
}

function findArchitectMapEntry(entries, canonicalSite, requestedSite, hostContext) {
    const rows = Object.values(entries || {});
    const mapped = rows.filter(entry => getDungeonMapAttachment(entry));
    const canonical = mapped.find(entry => {
        const attachment = getDungeonMapAttachment(entry);
        return dungeonSiteRootsMatch(attachment.siteRoot, canonicalSite);
    });
    if (canonical) return canonical;
    if (hostContext) {
        const compatibleLegacy = mapped.find(entry => {
            const attachment = getDungeonMapAttachment(entry);
            if (!dungeonSiteRootsMatch(attachment.siteRoot, requestedSite)) return false;
            const document = parseDungeonMapDocument(attachment.content, attachment.siteRoot).document;
            return !document.hostSite || document.hostSite === hostContext.hostSite;
        });
        if (compatibleLegacy) return compatibleLegacy;
        return rows.find(entry => String(entry?.comment || '').trim() === canonicalSite) || null;
    }
    return rows.find(entry => {
        const label = String(entry?.comment || '').trim();
        return label && !label.includes('::') && dungeonSiteRootsMatch(label, canonicalSite);
    }) || null;
}

// ── router.js: function mapTransactionSignature(value) { ──
function mapTransactionSignature(value) {
    const canonicalize = item => {
        if (Array.isArray(item)) return item.map(canonicalize);
        if (item && typeof item === 'object') {
            return Object.fromEntries(Object.keys(item).sort().map(key => [key, canonicalize(item[key])]));
        }
        return item;
    };
    const source = JSON.stringify(canonicalize(value));
    let hash = 0x811c9dc5;
    for (let index = 0; index < source.length; index++) {
        hash ^= source.charCodeAt(index);
        hash = Math.imul(hash, 0x01000193);
    }
    return (hash >>> 0).toString(16).padStart(8, '0');
}

    return {
        MAX_HOSTED_MAP_DEPTH,
        buildHostedPeerSitePath, reparentHostedLocationEntries, rebaseHostedMapDocuments, ensureHostCoreMirror,
        buildHostedPeerBrief, stampHostedPeerDocument,
        normalizeMapAttachment, resolveHostedCreationContext,
        allocateHostedAssetId, promoteHostedPeerAsset, findArchitectMapEntry, mapTransactionSignature,
    };
